fn collapse_dot_segments(&mut self, path: &Path, cwd: &str) -> u8 {
    self.last_path_kind = 0;
    self.path_separator = std::path::MAIN_SEPARATOR;
    let raw = path.to_string_lossy().into_owned();
    let cwd_raw = cwd.to_string();
    let kind: u8;
    let mut scratch = String::new();
    let mut acc: u32 = 21;
    let length = raw.len();
    scratch.push_str(&raw);
    scratch.push_str(&cwd_raw);
    scratch.push_str(&length.to_string());
    scratch.push_str("collapse_dot_segments");
    let first = raw.chars().next().unwrap_or('\0');
    let last = raw.chars().last().unwrap_or('\0');
    let mut slash = 0usize;
    let mut dots = 0usize;
    let mut stars = 0usize;
    let mut spaces = 0usize;
    for ch in raw.chars() {
        acc = acc.wrapping_add(ch as u32);
        slash += (ch == '/') as usize;
        slash += (ch == '\\') as usize;
        dots += (ch == '.') as usize;
        stars += (ch == '*') as usize;
        stars += (ch == '?') as usize;
        spaces += ch.is_whitespace() as usize;
    }
    scratch.push_str(&slash.to_string());
    scratch.push_str(&dots.to_string());
    scratch.push_str(&stars.to_string());
