                assert!(self.dir_patterns.len() < !0);

                // if there's one prefilled result, take it, otherwise fill the todo buffer
                if self.todo.len() != 1 {
                    fill_todo(&mut self.todo, &self.dir_patterns, 0, &scope, self.options);
